export declare const STYLE_ID = "dsh-pi-ai-auth-provider-card-style";
export declare const styles = "\n.dsh-pi-auth-row {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  min-height: 28px;\n  padding-top: 10px;\n  border-top: 0.5px solid var(--dsw-alias-border-l4);\n}\n.dsh-pi-auth-status {\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  min-width: 0;\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n  line-height: 18px;\n}\n.dsh-pi-auth-row > button { margin-left: auto; flex: none; }\n.dsh-pi-auth-error {\n  margin: 8px 0 0;\n  color: var(--dsw-alias-state-error-primary);\n  font-size: 12px;\n  line-height: 18px;\n}\n.dsh-pi-auth-modal-body { display: flex; flex-direction: column; gap: 14px; }\n.dsh-pi-auth-notice,\n.dsh-pi-auth-waiting,\n.dsh-pi-auth-prompt-label {\n  margin: 0;\n  color: var(--dsw-alias-label-secondary);\n  font-size: 14px;\n  line-height: 22px;\n}\n.dsh-pi-auth-link {\n  color: var(--dsw-alias-brand-primary);\n  font-size: 14px;\n  line-height: 22px;\n  text-decoration: none;\n}\n.dsh-pi-auth-link:hover { text-decoration: underline; }\n.dsh-pi-auth-code {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n  padding: 10px 12px;\n  border: 0.5px solid var(--dsw-alias-border-l4);\n  border-radius: 10px;\n  color: var(--dsw-alias-label-secondary);\n  font-size: 12px;\n}\n.dsh-pi-auth-code code { color: var(--dsw-alias-label-primary); font-size: 14px; user-select: all; }\n.dsh-pi-auth-select {\n  box-sizing: border-box;\n  width: 100%;\n  height: 36px;\n  padding: 0 10px;\n  border: 0.5px solid var(--dsw-alias-border-l4);\n  border-radius: 8px;\n  background: var(--dsw-alias-bg-layer-1);\n  color: var(--dsw-alias-label-primary);\n  font: inherit;\n}\n.dsh-pi-auth-footer { display: flex; justify-content: flex-end; gap: 8px; }\n";
